use vstd::prelude::*;

verus! {

/// Reverse a non‐empty vector of characters.
/// 
/// Requires:
///   - a.len() > 0
/// Ensures:
///   - b.len() == a.len()
///   - ∀ i < a.len(): b[i] == a[a.len() - 1 - i]
fn reverse(a: &Vec<char>) -> (b: Vec<char>)
    requires
        a.len() > 0,
    ensures
        b.len() == a.len(),
        forall(|i: usize| i < a.len() ==> b[i] == a[a.len() - 1 - i]),
{
    let mut b: Vec<char> = Vec::new();
    let n: usize = a.len();
    // Pre‐allocate capacity for efficiency
    b.reserve(n);

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            b.len() == i,
            // For all j < i, we have already reversed those positions
            forall(|j: usize| j < i ==> b[j] == a[n - 1 - j]),
        decreases n - i,
    {
        // Compute the index in `a` to copy
        let idx: usize = n - 1 - i;
        // Safety check: since i < n, idx < n
        assert(idx < n);
        let c: char = a[idx];
        b.push(c);
        i = i + 1;
    }

    // At loop exit, i == n, so b.len() == n and
    // ∀ j < n: b[j] == a[n - 1 - j]
    b
}

} // end of verus!

